"""RMSNorm kernels."""

from typing import Any

__all__ = [
    "add_rmsnorm",
    "add_rmsnorm_into",
    "add_rmsnorm_torch",
    "rmsnorm",
    "rmsnorm_into",
    "rmsnorm_torch",
]


def __getattr__(name: str) -> Any:
    if name in {"add_rmsnorm", "add_rmsnorm_into", "rmsnorm", "rmsnorm_into"}:
        from kestrel_kernels.rmsnorm import dispatch

        return getattr(dispatch, name)
    if name in {"add_rmsnorm_torch", "rmsnorm_torch"}:
        from kestrel_kernels.rmsnorm import fallback

        return getattr(fallback, name)
    raise AttributeError(f"module {__name__!r} has no attribute {name!r}")
